-- DNP photographs - one-shot data load.
--
-- Fills the photo columns 200_dnp_media.sql added, from the media the importer
-- infra/mcp/scripts/enrich-dnp-media.mjs already collected and cached. This is
-- byte-for-byte the UPDATE that script's final flush runs, so it does the same
-- thing when there is no server-side route to run the importer - paste it into
-- the deployed database (e.g. the Easypanel SQL console) instead.
--
--   1560 plant row(s), joined on gbif_key
--   0 animal row(s), joined on scientific_name
--
-- Idempotent: it sets the same values every time, so running it twice is safe,
-- and a plant whose gbif_key is absent from the table is simply not matched.
-- The images are openly licensed (iNaturalist open data first, any publisher as
-- a fallback); attribute photo_credit.
--
-- Regenerate from the cache after a fresh enrichment run:
--   DATABASE_URL=... DNP_MEDIA_FLUSH_ONLY=1 node infra/mcp/scripts/enrich-dnp-media.mjs
-- then rebuild this file from infra/mcp/scripts/.cache/dnp-media-enrich.json.
--
-- Generated by a throwaway script; this file itself is the artifact to run.

begin;

-- api.dnp_plants - 4 batched update(s) of up to 500 keys.

update api.dnp_plants as p set
  photo_url     = v.photo_url,
  photo_source  = v.photo_source,
  photo_license = v.photo_license,
  photo_credit  = v.photo_credit,
  photo_ref     = v.photo_ref
